//
//  ClipboardMonitor.swift
//  HaoPaste
//
//  Polls NSPasteboard.general and filters out concealed / transient content.
//

import AppKit

@MainActor
final class ClipboardMonitor {
    private static let concealedTypeNames: Set<String> = [
        "org.nspasteboard.concealedtype",
        "org.nspasteboard.transienttype",
        "org.nspasteboard.autogeneratedtype"
    ]

    private static let sensitiveTypePrefixes = [
        "com.agilebits.onepassword",
        "com.1password",
        "com.bitwarden",
        "com.lastpass",
        "org.keepassxc",
        "com.dashlane"
    ]

    private let pasteboard: NSPasteboard
    private var lastChangeCount: Int
    private var pollingTask: Task<Void, Never>?
    private var activityToken: NSObjectProtocol?

    private(set) var isPaused = false
    var onCapture: ((CapturedClipboard) -> Void)?

    init(pasteboard: NSPasteboard = .general) {
        self.pasteboard = pasteboard
        self.lastChangeCount = pasteboard.changeCount
    }

    func start() {
        guard pollingTask == nil else { return }

        lastChangeCount = pasteboard.changeCount
        activityToken = ProcessInfo.processInfo.beginActivity(
            options: [.userInitiatedAllowingIdleSystemSleep, .suddenTerminationDisabled],
            reason: "Monitor clipboard changes"
        )
        pollingTask = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                try? await Task.sleep(nanoseconds: 350_000_000)
                guard !Task.isCancelled, let self else { break }
                self.poll()
            }
        }
    }

    func stop() {
        pollingTask?.cancel()
        pollingTask = nil

        if let activityToken {
            ProcessInfo.processInfo.endActivity(activityToken)
            self.activityToken = nil
        }
    }

    func setPaused(_ paused: Bool) {
        isPaused = paused
        if !paused {
            // Do not capture anything that changed while monitoring was paused.
            synchronizeChangeCount()
        }
    }

    /// Called after the app itself writes to the pasteboard.
    func synchronizeChangeCount() {
        lastChangeCount = pasteboard.changeCount
    }

    // MARK: - Polling

    private func poll() {
        guard !isPaused else { return }

        let changeCount = pasteboard.changeCount
        guard changeCount != lastChangeCount else { return }
        lastChangeCount = changeCount

        guard !containsConcealedData else { return }
        guard let capture = makeCapture() else { return }
        onCapture?(capture)
    }

    private var containsConcealedData: Bool {
        guard let types = pasteboard.types else { return false }

        return types.contains { type in
            let rawValue = type.rawValue.lowercased()

            if Self.concealedTypeNames.contains(rawValue) {
                return true
            }

            return Self.sensitiveTypePrefixes.contains { rawValue.hasPrefix($0) }
        }
    }

    private func makeCapture() -> CapturedClipboard? {
        let imageData = pasteboard.data(forType: .png) ?? pasteboard.data(forType: .tiff)
        let string = pasteboard.string(forType: .string)
        let trimmedString = string?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        // Images win only when there is no meaningful text representation.
        if let imageData, trimmedString.isEmpty {
            guard let dimensions = ImageProcessor.dimensions(of: imageData) else { return nil }

            return CapturedClipboard(
                payload: .image(imageData, dimensions: dimensions),
                plainText: "图片 \(dimensions.displayText)",
                contentHash: ContentHasher.imageData(imageData),
                sourceApp: currentSourceApplication()
            )
        }

        guard let string, !trimmedString.isEmpty else { return nil }

        let type = ContentClassifier.classify(string)
        return CapturedClipboard(
            payload: .text(string, type: type),
            plainText: string,
            contentHash: ContentHasher.text(string, type: type),
            sourceApp: currentSourceApplication()
        )
    }

    private func currentSourceApplication() -> SourceApplication? {
        guard let app = NSWorkspace.shared.frontmostApplication else { return nil }

        // Never record ourselves as the source.
        guard app.processIdentifier != ProcessInfo.processInfo.processIdentifier else {
            return nil
        }

        return SourceApplication(
            bundleIdentifier: app.bundleIdentifier,
            name: app.localizedName ?? "未知应用"
        )
    }
}
